def home(request):
    return render(request, "home.html", {"characters": CHARACTERS[:12], "timeline": TIMELINE, "factions": FACTIONS[:3], "quotes": Quote.objects.all()[:4], "adaptations": ADAPTATIONS})

def history(request):
    return render(request, "history.html", {"timeline": TIMELINE, "plot_arcs": PLOT_ARCS, "adaptations": ADAPTATIONS})

def plot(request):
    return render(request, "plot.html", {"plot_arcs": PLOT_ARCS})

def adaptations(request):
    return render(request, "adaptations.html", {"adaptations": ADAPTATIONS})

def characters(request):
    return render(request, "characters.html", {"characters": CHARACTERS})

def character(request, slug):
    person = next((item for item in CHARACTERS if item["slug"] == slug), None)
    if person is None:
        from django.http import Http404
        raise Http404("Character not found")
    return render(request, "character.html", {"person": person})

def factions(request):
    return render(request, "factions.html", {"factions": FACTIONS})

def quotes(request):
    return render(request, "quotes.html", {"quotes": Quote.objects.all(), "characters": CHARACTERS})

def gallery(request):
    return render(request, "gallery.html", {"gallery": GalleryItem.objects.all(), "characters": CHARACTERS})
